// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":273,"question":"رجلٌ غنيٌّ يُتاجر في أشياء مُحرَّمة شرعًا، وكل ماله ناتجٌ من هذا المُحرَّم، و هل من الممكن أن يُشارك هذا الرجل في أعمال البرِّ: كالتبرع إلى الأفغان وغيرهم، كما أحبَّ من سماحتكم أن تُبَيِّنوا لنا بشيءٍ من التَّفصيل حكم كفالة اليتيم، وهل مشروع كافل اليتيم التابع لرابطة العالم الإسلامي -مؤسسة مكة المكرمة- موثوقٌ أم لا؟ أجيبونا أثابكم الله.","title":"حكم تبرُّع من كانت أمواله من الحرام؟","answer":"الجواب: مَن كانت عنده أموال وصلت إليه بغير طريقٍ شرعيٍّ، فصرفها في وجوه البِرِّ؛ نرجو أن يبرأ منها، مع التوبة، إذا تاب إلى الله وندم وصرفها في وجوه البِرِّ: إلى الفقراء والمساكين، والمصالح العامَّة، وأداء الديون، وتزويج المُحتاجين للزواج، وأشباه ذلك، نرجو له في هذا البراءة والعافية، وأن يُؤجر على قصده الصالح، وتوبته الصَّادقة.\nهذا هو الذي ينبغي لمَن بُلي بهذه الأمور: أن يصرفها في وجوه الخير وأعمال البِرّ، حتى يبرأ من عهدتها، ويسلم من تبعتها، مع التوبة الصَّادقة والنَّدم.\nوأما صندوق كافل اليتيم الذي عند الرابطة، فالرابطة في هذا وأمثالها لا شكَّ أنها موثوقٌ بها، وعندها بحمد الله نشاطٌ كبيرٌ في مصالح المسلمين، وهذا من مصالح المسلمين، ولا سيما أيتام المُجاهدين الأفغان، فمَن ساعد في هذا وكفل يتيمًا أو أكثر فهو على خيرٍ عظيمٍ، وله أجرٌ كبيرٌ، فالنبي ﷺ قال: أنا وكافل اليتيم كهاتين وشبَّك بين أصبعيه: الوسطى والسَّبابة.","link":"https://binbaz.org.sa/fatwas/4270/حكم-تبرع-من-كانت-امواله-من-الحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0319.mp3","categories":["صدقة التطوع"]},{"id":683,"question":"ما نقص مال من صدقة؟","title":"معنى \"ما نقص مال من صدقة\" بالحديث","answer":"الجواب: ج: يزيد البركة.\n(دروس شرح بلوغ المرام، كتاب الجامع)","link":"https://binbaz.org.sa/fatwas/6830/معنى-ما-نقص-مال-من-صدقة-بالحديث","audio":"undefined","categories":["صدقة التطوع"]},{"id":686,"question":"إطعام الطعام هو التصدُّق؟","title":"ما معنى \"إطعام الطعام\" في الحديث؟","answer":"الجواب: إطعام الطعام: يجيب الناس يأكلون، أو يتصدق به.\n(دروس شرح بلوغ المرام، كتاب الجامع)","link":"https://binbaz.org.sa/fatwas/6833/ما-معنى-اطعام-الطعام-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/maram254 - 03 - .mp3","categories":["صدقة التطوع"]},{"id":1524,"question":"إذا وجد فقيرًا ومسكينًا ذا قربى فمَن يُقدِّم؟","title":"هل تُقَدَّم الصدقة للمسكين القريب على غيره؟","answer":"الجواب:\nكلهم ذا قربى؟\nس: الفقير غير قريب، والمسكين هو ذو القربى؟\nج: يقول النبي ﷺ: الصدقة على الفقير صدقة، وعلى ذي الرحم اثنتان: صدقة وصلة، فالقريب الفقير والمسكين أولى من غيره؛ لأنه في حقِّه اثنتان، يكون للمؤمن فيها اثنتان: صدقة وصلة رحم.","link":"https://binbaz.org.sa/fatwas/21623/هل-تقدم-الصدقة-للمسكين-القريب-على-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من يقدم في الصدقة الفقيرة أو المسكين ذا القربى.mp3","categories":["صدقة التطوع"]},{"id":1525,"question":"الأشد فالأشد في الآية أو أي واحدٍ يُجزئ؟","title":"مسألة في الصدقة على الفقراء","answer":"الجواب:\nعلى كل حال أي واحدٍ يجزئ من الفقراء، لكن إذا تحرى الإنسانُ المتعففَ وتحرَّى الأشدَّ فاقة يكون أحسن وأفضل، فالمتصدِّق يتحرى الأشد حاجة، ويتحرى المتعفف، لكن لا شك أن هذا أفضل.","link":"https://binbaz.org.sa/fatwas/21625/مسالة-في-الصدقة-على-الفقراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الصدقة على الفقراء.mp3","categories":["صدقة التطوع"]},{"id":1540,"question":"ما أفضل الصدقة: أن تكون بالنقود أو بالأكل؟","title":"هل الصدقة بالنقود أفضل أم بالطعام؟","answer":"الجواب:\nبما تيسر، وبما هو أنفع للفقير.","link":"https://binbaz.org.sa/fatwas/21640/هل-الصدقة-بالنقود-افضل-ام-بالطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أفضل الصدقة.mp3","categories":["صدقة التطوع"]},{"id":1572,"question":"كيف نجمع بين قوله عليه الصلاة والسلام: خير الصدقة ما كان عن ظهر غنًى وقوله: وأن تصدق وأنت صحيحٌ شحيحٌ؟","title":"معنى حديث \"أن تَصَدَّق وأنت صحيحٌ شحيحٌ\"","answer":"الجواب:\nيعني: بعدما يفضل من عائلته، يبدأ بمن يجب عليه، فإذا كان عنده فضل يتصدق.","link":"https://binbaz.org.sa/fatwas/21675/معنى-حديث-ان-تصدق-وانت-صحيح-شحيح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين حديث خير الصدقة ما كان عن ظهر غنًى وقوله وأن تصدق وأنت صحيحٌ شحيحٌ.mp3","categories":["صدقة التطوع"]},{"id":1581,"question":"مال الحجَّام هل يتصدق منه؟","title":"هل تجوز الصدقة من مال الحجَّام؟","answer":"الجواب:\nيتصدق نعم.\nس: ما هو برديء؟\nج: لا، يتصدق، النبي ﷺ أمر بالصدقة، وأعطى أبا طيبة أجرة الحجامة، لكنه كسب خبيث رديء، يتصدق منه، هذا ماله، الكسب الرديء، كلٌّ يتصدق على قدر ما عنده، فالذي ما عنده إلا تمر رديء يتصدق منه، والذي عنده ملابس ما هي بجيدة يتصدق منها، كلٌّ على قدره: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].","link":"https://binbaz.org.sa/fatwas/21684/هل-تجوز-الصدقة-من-مال-الحجام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يتصدق من مال الحجَّام.mp3","categories":["صدقة التطوع"]},{"id":1621,"question":"صدقة المرأة على زوجها هل هي تطوع؟","title":"حكم صدقة المرأة وزكاتها لزوجها","answer":"الجواب:\nتطوع، والزكاة فيها خلاف، والأرجح جوازها في الزكاة.","link":"https://binbaz.org.sa/fatwas/21726/حكم-صدقة-المراة-وزكاتها-لزوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صدقة المرأة على زوجها.mp3","categories":["إخراج الزكاة وأهلها","صدقة التطوع"]},{"id":1652,"question":"رجلٌ عنده امرأة من أهل البيت، وهو له راتبٌ من الصَّدقة، فهل تأكل منه أم ماذا تفعل؟","title":"حكم إعطاء أهل البيت من الصدقة","answer":"الجواب:\nإذا وصلت إليه فقد وصلت إلى محلِّها، فلا بأس أن يُعطي منها أهلَ البيت، مثلما أخبر النبيُّ ﷺ: هو عليها صدقة، ولنا هدية من أم عطية، ومن بريرة، فإذا وصلت الصدقة -الزكاة- إلى أهلها فأهدوا منها إلى أهل البيت هديةً أو عزموهم على طعامٍ فلا بأس بذلك؛ لأنها وصلت إلى محلِّها.","link":"https://binbaz.org.sa/fatwas/21757/حكم-اعطاء-اهل-البيت-من-الصدقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم إعطاء أهل البيت من الصدقة.mp3","categories":["صدقة التطوع"]},{"id":2094,"question":"السّبائب والأوقاف تجوز لآل البيت؟","title":"ما حكم الأوقاف والصدقات لآل البيت؟","answer":"الجواب:\nنعم، نعم، لكن يُمنعون من الزكاة خاصَّةً فقط، أما الصدقات الأخرى فلا بأس بها.","link":"https://binbaz.org.sa/fatwas/22212/ما-حكم-الاوقاف-والصدقات-لال-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما الذي يجوز لآل البيت.mp3","categories":["صدقة التطوع"]},{"id":2139,"question":"إذا أشرفت نفسُ الفقير المستحقّ فعلًا للعطاء والزكاة، فهل يكون مذمومًا، مع أنه يحتاج إلى ذلك بالفعل، وهو مستحقٌّ له شرعًا، أو المقصود الإشراف لما لا يستحقّ؟","title":"حكم إشراف النفس للمال عن استحقاق له","answer":"الجواب:\nالأقرب -والله أعلم- أنه لما لا يستحق، يعني: التَّزود والاستكثار. وأما طلب الفقير حاجته فلا بأس، من الزكاة وغيرها.","link":"https://binbaz.org.sa/fatwas/22257/حكم-اشراف-النفس-للمال-عن-استحقاق-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فوائد في مسألة الناس.mp3","categories":["صدقة التطوع"]},{"id":2151,"question":"هل يُقاس على السلطان الذي عنده مالٌ وائتمنه الأغنياءُ عليه ليُوزِّعه في حاجات الناس؟ فهل تصرفاته في أعمال البر تكون مثل السلطان في هذه المسألة وهو ليس السلطان العام؟","title":"ما سلطة المُؤتمن على مال الأغنياء لتوزيعه؟","answer":"الجواب:\nما هو مثل السلطان، لكن إذا دعت الضَّرورةُ يسأل: له أو لغيره.\nس: ليس المالُ مالَ هذا الرجل بل هو مال الناس؟\nج: ولو، لا يسأل إلا عند الحاجة والضَّرورة.","link":"https://binbaz.org.sa/fatwas/22270/ما-سلطة-الموتمن-على-مال-الاغنياء-لتوزيعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من ائتمنه الأغنياءُ على مال ليوزعه هل يقاس على السلطان.mp3","categories":["صدقة التطوع"]},{"id":2162,"question":"ما الأفضل: التّصدق بثُلُث المال أم بالمال كله؟","title":"هل الأفضل التّصدق بثلث المال أم به كله؟","answer":"الجواب:\nلا بدّ أن يُبقي له ما ينفعه ولا يتصدّق به كله، مثلما قال ﷺ لكعبٍ: أمسك عليك بعض مالك فهو خيرٌ لك، فيتصدّق بما تيسَّر، ويُبقي ما يُعينه على طاعة الله، ويُنفق على أهله.","link":"https://binbaz.org.sa/fatwas/22283/هل-الافضل-التصدق-بثلث-المال-ام-به-كله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الأفضل التّصدق بثلث المال أم بالمال كله.mp3","categories":["صدقة التطوع"]},{"id":2174,"question":"إذا كثر السَّائلون فهل على الذي يُسْأَل أن يتثبَّت؟","title":"هل على المُعطي أن يتثبت إذا كثر السَّائلون؟","answer":"الجواب:\nيبدأ بالأهم فالأهم، الأحوج فالأحوج، يتثبت في الأمور؛ لأنَّ بعض الناس يسأل وعنده مال، فبعض الناس عنده حرصٌ على المال، وإن كان مليئًا، فعلى المعطي أن يتثبت إذا سأله إنسان حتى يكون على بصيرةٍ.\nس: وإذا ظهر له أنه كاذب أو فعل شيئًا وغير صادق، ماذا عليه أن يفعل؟\nج: لا يعطيه، ويعطي الآخرين، فقد جاءه ﷺ رجلان يسألاه، فرآهما جَلْدَين، فقال: إن شئتُما أعطيتُكما، ولا حظَّ فيها لغنيٍّ ولا لقويٍّ مُكْتَسِب  يعني: الزكاة.\nس: أمسك أحد الإخوة طفلًا في الحرم المكي يطلب، فكان يضع يده وكأنها مكسورة، فلما أمسكها ظهر أنها غير مكسورة؟\nج: بعضهم يتحايل ويكذب، والإثم عليه.\nس: ولكن مَن أمسك هذا الطفل ماذا عليه أن يفعل؟\nج: عليه أن ينصحه ويُعلمه أن هذا ما يجوز.\nس: ولو قال: نصحته وعاد؟\nج: ولو، يعلمه، أو يرفع أمره إلى رجال حسبة المسجد.","link":"https://binbaz.org.sa/fatwas/22295/هل-على-المعطي-ان-يتثبت-اذا-كثر-الساىلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا كثر السَّائلون فهل على الذي يُسْأَل أن يتثبَّت.mp3","categories":["صدقة التطوع"]},{"id":2201,"question":"إذا كان في المال شُبهة، هل يُوزّعه على الفقراء والمساكين ويُعرِّفهم أنَّ المال فيه شُبهة؟","title":"ما حكم التصرف في المال الذي به شُبْهة؟","answer":"الجواب:\nلا، يُعطيهم إيَّاه فقط، ولا يقول لهم شيئًا.\nس: وحديث: إنَّ الله طيِّبٌ لا يقبل إلا طيِّبًا؟\nج: ما فيه بأس؛ لأنَّ هذا مصرف المشتبهات.","link":"https://binbaz.org.sa/fatwas/22324/ما-حكم-التصرف-في-المال-الذي-به-شبهة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المال إذا كان فيه شبهة.mp3","categories":["صدقة التطوع"]},{"id":2340,"question":"رجلٌ يأمر ولدين له أن يذهبا إلى المَبَرَّة ليأتيا بشيءٍ من الصَّدقات، يقول هذان الولدان: هل يجوز لنا أن نمتنع من أمر والدنا لنا؛ لأننا مُقتدرون، ولا نريد الذهابَ إلى هذه المَبَرَّة؟","title":"ما حكم أغنياء يأمرهم أبوهم بأخذ الصدقة؟","answer":"الجواب:\nإذا كانوا أغنياء لا يجوز لهم، فالمبرة للفقراء، فيُعَلِّما والدهما ويقولا: ما تجوز لنا، ما تصحّ لنا. وإنما الطاعة في المعروف، أمَّا إذا كانوا فقراء فلا بأس.\nس: لو ما يكفيهم، لكن عظيم حياءٍ منهم لا يُريدون أصلًا الذهابَ إلى هذه المَبَرَّة؟\nج: المقصود أنهم إذا كانوا فقراء يُلزمون بطاعة والدهم، وإن لم يكونوا فقراء فلا تلزمهم طاعةُ والدهم، أما الحياء فليس له محلٌّ في هذا.","link":"https://binbaz.org.sa/fatwas/22464/ما-حكم-اغنياء-يامرهم-ابوهم-باخذ-الصدقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/يأمرهم أبوهم بأن يأخذوا من مال الصدقة وهم أغنياء.mp3","categories":["صدقة التطوع"]},{"id":2435,"question":"المتهاون من الصلاة يُعطى من الصدقة، مثلًا يصلي في البيت؟","title":"ما حكم الصدقة على المتهاون بالصلاة؟","answer":"الجواب:\nيُعطى من الصدقة لكن لغيره أطيب، الذي غيره المحافظ أولى بالإحسان إذا كان يصلي، إذا كان يصلي في البيت يكون عاصيًا، أما إذا كان ما يصلي ما يُعطى من الزكاة، يُعطى من غير الزكاة من باب التأليف إذا كان فقيرًا مع النصيحة والتوجيه.\nس: وهو محتاج مثلًا عليه ديْن مثلًا؟\nالشيخ: إذا كان يصلي لا بأس؛ يُعطى ويُنصح ويُؤدب، الهيئة تؤدبه إذا تخلف، إذا رفع الأمر  إلى الهيئة.","link":"https://binbaz.org.sa/fatwas/22564/ما-حكم-الصدقة-على-المتهاون-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المتهاون من الصلاة هل يعطى من الصدقة.mp3","categories":["إخراج الزكاة وأهلها","صدقة التطوع"]},{"id":2436,"question":"نحن في جمعية خيرية ويتقدم كثير من الروافض لمساعدتهم وهم فقراء مستحقون المساعدة، فهل تُخفى خطاباتهم أو يُعطون من الصدقات؟","title":"حكم الزكاة والصدقة للفقراء من الروافض","answer":"الجواب:\nهذا يختلف، إذا كان تطوعًا من باب التأليف، النبي ﷺ كان يعطي الكفرة وغير الكفرة مثل ما قال الله جل وعلا: لَا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ  [الممتحنة:8] إذا كان فيه تأليف ودعوة لهم إلى السنة؛ لعل الله ينفع بالأسباب.\nس: مع أن تجارهم ما يدفعون؟\nالشيخ: المقصود: يُعْطَون من غير الزكاة، من باب التأليف إذا كان فيه دعوة مع الترغيب للسُّنة في وقت آخر، وإلا لا يعطيهم، يعطي أهل السُّنة والحمد لله، أما الزكاة فلا يُعطون الزكاة.","link":"https://binbaz.org.sa/fatwas/22565/حكم-الزكاة-والصدقة-للفقراء-من-الروافض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مساعدة الروافض المحتاجين.mp3","categories":["صدقة التطوع","إخراج الزكاة وأهلها"]},{"id":2594,"question":"من تصدق على شخص واكتشف أنه غني هل يسترد صدقته؟","title":"هل لمَنْ تصدّق على غنيٍّ أنْ يسترد صدقته؟","answer":"الجواب: إذا كان ظاهره الفقر ما يضره، إذا كان ظاهره الفقر وتشبه بالفقراء وظن أنه فقير وأعطاه؛ تجزئه عند العلماء، والإثم على ذلك.\nس: الذي لا يتصدق هل يأثم؟\nالشيخ: في الزكاة يأثم، أما في غير الزكاة ما يأثم، إلا إذا اضطر، الفقير عرف أنه مضطر يلزمه أنه ينقذه، لكن الواجب الزكاة، أما البقية على حسب الأسباب، الصدقات الأخرى على حسب الأسباب.","link":"https://binbaz.org.sa/fatwas/22727/هل-لمن-تصدق-على-غني-ان-يسترد-صدقته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تصدق على شخص وهو غني فهل يسترد صدقته.mp3","categories":["صدقة التطوع"]},{"id":2650,"question":"عند أهل نجد \"عشاء والدين\" هل في شيء فيه؟","title":"حكم ما يُسمّى \"عشاء الوالدين\" عند أهل نجد","answer":"الجواب: صدقة في رمضان يسمونها عشاء، لا بأس بها، الصدقة في رمضان مضاعفة، فإذا تصدق في رمضان وخصّه بمزيد صدقات أو في العشر الأخيرة؛ كان له فضله سواء، سمي عشاء الوالدين أو عشاء الأقارب أو عشاء الجيران أو عشاء الفقراء.\nس: أحسن الله إليك يخصّصونه بسبع وعشرين؟\nالشيخ: هذه يرجى ليلة القدر، هذا المقصود.\nس: ليس فيه شيء؟\nالشيخ: لا، لو خصها بمزيد نفقة ما يخالف؛ لأنها ليلة تعدل ألف شهر، العمل فيها كالعمل في ألف شهر، بل خير من ألف شهر.","link":"https://binbaz.org.sa/fatwas/22786/حكم-ما-يسمى-عشاء-الوالدين-عند-اهل-نجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم ما يفعله أهل نجد عشاء والدين.mp3","categories":["صدقة التطوع"]},{"id":2666,"question":"الترغيب في الإفطار: عندهم في الحَرَم يعطون فلوسًا على أساس يفطر عندهم؟","title":"حكم دعوة الصائم للإفطار لكسب الأجر","answer":"الجواب: صدقة مع الإفطار.","link":"https://binbaz.org.sa/fatwas/22804/حكم-دعوة-الصاىم-للافطار-لكسب-الاجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الترغيب للصائم في الإفطار لكسب الأجر.mp3","categories":["صدقة التطوع"]},{"id":2710,"question":"أفتى بعض كبار العلماء أن الأيام هذه البذل في سبيل الله أفضل من كثرة العمرة في رمضان وغير رمضان؟","title":"هل البذل والإنفاق أفضل من كثرة العمرة؟","answer":"الجواب: وأفضل مِن الحج بَعْد، يقول ﷺ لما سئل أي العمل أفضل؟ قال: إيمان بالله ورسوله قيل: ثم أي؟ قال: الجهاد في سبيل الله قيل: ثم أي؟ قال: الحج المبرور، الحج بعد الجهاد.\nس: يقولون: لا تكثروا العمرة، الأفضل لكم أن تعطوا المحاويج؟\nالشيخ: هذا محل اجتهاد، العمرة مشروعة وتكرارها مشروع، وإذا تصدّق؛ كُلُّه على خير.","link":"https://binbaz.org.sa/fatwas/22852/هل-البذل-والانفاق-افضل-من-كثرة-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل البذل في سبيل الله أفضل من كثرة العمرة.mp3","categories":["صدقة التطوع"]},{"id":3789,"question":"الراجح في الصَّدقة على بني هاشم؟","title":"ما الراجح في الصَّدقة على بني هاشم؟","answer":"الجواب: يُعطون من الصدقة غير الزكاة، الزكاة لا تنبغي لآل محمدٍ، إنما هي أوساخ الناس يقول النبيُّ ﷺ، لكن بعض أهل العلم قال: إذا اضطروا إليها جاز، إذا لم يُعطوا من بيت المال ما يكفيهم، ولكن في النفس منه شيء، الأولى بهم أن يتنزَّهوا عنها، ويلتمسوا الأعمال الحرة والعمل والكسب حتى يستغنوا عنها.\nس: ما فهمت، الفتوى: هل نعطيهم أم لا؟\nالشيخ: لا يعطون من الزكاة، ولا يجوز لهم أخذها، لكن بعض أهل العلم يقول إذا اضطروا إليها كالميتة.\nس: وزكاتهم على فقرائهم؟\nالشيخ: لا، يعطونها غير الفقراء؛ لأن الحديث عام.","link":"https://binbaz.org.sa/fatwas/23987/ما-الراجح-في-الصدقة-على-بني-هاشم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الراجح في الصَّدقة على بني هاشم.mp3","categories":["صدقة التطوع"]},{"id":4219,"question":"الرجل يتصدق على زوجات أولاده؟","title":"هل تُستحب الصدقة على زوجات أولاده؟","answer":"الجواب: إذا كن فقيرات، أولاده فقراء، نعم.","link":"https://binbaz.org.sa/fatwas/24486/هل-تستحب-الصدقة-على-زوجات-اولاده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يتصدق الرجل على زوجات أولاده.mp3","categories":["صدقة التطوع"]},{"id":4221,"question":"هذا رجل نصراني وقف في المستشفى ويريد جمع مال لأجل يعمل عملية؟","title":"حكم الصدقة على الكافر غير المحارب","answer":"الجواب: الصدقة عليه مشروعة، ما هو بحربي، الصدقة طيبة على مريض في المستشفى، كافر أو مستأمن محتاج، أو ما أشبهه، أو مُعاهد محتاج، فالصدقة فيه فيها أجر عظيم، لكن في المسلمين أفضل، إذا وجد هذا وهذا، فالمسلم أفضل، ولكن إذا جاد على هذا وعلى هذا وتصدق على هذا وعلى هذا؛ فهذا له الأجر العظيم.\nس: إذا كان يضع الصليب على يده أو على صدره؟\nالشيخ: ولو علق بالصليب، الشرك بالله أعظم، عبادة عيسى أعظم، وعبادة مريم أعظم من الصليب، ومع هذا يُعطى، يتصدق عليه تأليفًا له، الله قال: وَالْمُؤَلَّفَةِ قُلُوبُهُمْ [التوبة:60].","link":"https://binbaz.org.sa/fatwas/24488/حكم-الصدقة-على-الكافر-غير-المحارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصدقة على الكافر غير المحارب.mp3","categories":["صدقة التطوع"]},{"id":4225,"question":"إذا خصّه الفقير بالسؤال وهو قادر يتعيّن عليه أن يعطيه؟","title":"حكم مَنْ خصَّه الفقير بالسؤال وهو قادر","answer":"الجواب: الله يقول جل وعلا: وَفِي أَمْوَالِهِمْ حَقٌّ لِلسَّائِلِ وَالْمَحْرُومِ [الذاريات:19] المحروم الفقير، والسائل الذي يسألك، قد يكون له حاجة وأنت ما تدري، تعطيه ولو قليل، هذا الذي ينبغي وَفِي أَمْوَالِهِمْ حَقٌّ لِلسَّائِلِ وَالْمَحْرُومِ [الذاريات:19]، قال بعضهم: الزكاة، والأقرب أن الآية عامة، تعم الزكاة وغيرها، إلا إذا عرفت أنه يستكثر، وأنه مغنيه الله، لا، يُنصح ويُوجه إلى الخير؛ حتى يحذر السؤال الذي يضره ويغضب الله عليه.","link":"https://binbaz.org.sa/fatwas/24492/حكم-من-خصه-الفقير-بالسوال-وهو-قادر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا خص الفقير بالسؤال شخصا وهو قادر يتعين عليه أن يعطيه.mp3","categories":["صدقة التطوع"]},{"id":4728,"question":"في رمضان ما يفعله بعضُ الناس مما يُسمَّى: عشاء الوالدين؛ يذبح بعضَ الغنم ويُقدمها للفقراء والمساكين؟","title":"حكم ما يُسمَّى بعشاء الوالدين","answer":"صدقة، لا بأس، لا حرج، لكن صدقة في رمضان، إذا جاء رمضان تُضاعف فيه الحسنات، فإذا ذبح وقسَّم ذلك على الفقراء، عن نفسه أو عن أهل بيته أو عن جمعهم؛ اغتنامًا لفضل رمضان أو العشر من ذي الحجة؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/25037/حكم-ما-يسمى-بعشاء-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم ما يُسمَّى بعشاء الوالدين.mp3","categories":["صدقة التطوع"]},{"id":5017,"question":"إذا علم الشخصُ أنه مُتَسَوِّل فهل يُعطى؟","title":"هل يُعطي السائل إنْ عُلم أنه مُتَسَوِّل؟","answer":"الجواب: نعم، وَفِي أَمْوَالِهِمْ حَقٌّ لِلسَّائِلِ وَالْمَحْرُومِ [الذاريات:19] يُعطى السائل.","link":"https://binbaz.org.sa/fatwas/28830/هل-يعطي-الساىل-ان-علم-انه-متسول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يعطى السائل إن علم أنه متسول؟.mp3","categories":["صدقة التطوع"]},{"id":5018,"question":"إذا كان شخصٌ يسأل ولكن من أجل الدعوة: كبناء المساجد أو..؟","title":"حكم مَن يسأل المال من أجل الدعوة والمساجد","answer":"الجواب: هذه شفاعة لأهل الخير يدعوهم فيها إلى الخير، فيشفع لمَن يعمرون مسجدًا، أو للذين يشترون كتبًا ليُوزِّعوها على الطلبة، أو في بناء مدرسة، فهذا داخلٌ في قوله: مَنْ يَشْفَعْ شَفَاعَةً حَسَنَةً [النساء:85].","link":"https://binbaz.org.sa/fatwas/28828/حكم-من-يسال-المال-من-اجل-الدعوة-والمساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من يسأل المال من أجل الدعوة والمساجد.mp3","categories":["صدقة التطوع"]},{"id":5405,"question":"هل كل مَن يأتيك يسأل تُعطيه؟","title":"هل يُعطى كل مَنْ يسأل؟","answer":"الجواب: وَفِي أَمْوَالِهِمْ حَقٌّ لِلسَّائِلِ وَالْمَحْرُومِ [الذاريات:19]، إلا إذا علمتَ أنه كذَّاب فازجره وانصحه، إذا علمت أنه كذَّاب فهذا يُنصح ويُعَلَّم ويُنكر عليه. أمَّا إذا كان مجهولًا أو تعرف حاجتَه فالسُّنة أن تُعطيه ما تيسَّر.[1]","link":"https://binbaz.org.sa/fatwas/31164/هل-يعطى-كل-من-يسال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 021.mp3","categories":["صدقة التطوع"]},{"id":6252,"question":"وآت ذا القربى حقه أليس ذلك الزكاة، أو هي نفقة خاصة دون الزكاة؟","title":"عموم قوله: (وَآتِ ذَا الْقُرْبَى حَقَّهُ) في الزكاة والصلة وغيرهما","answer":"الجواب: \nهذا عام، إيتاء ذي القربى حقه، صلة الرحم حق، إذا كان فقيرًا؛ يعطى حقه صلة الرحم، وإذا كان عاجزًا؛ أعطاه من الزكاة، فكل هذا له حق في الزكاة، وله حق في مال قريبه إذا كان فقيرًا، فالآية تعم هذا، وهذا، تعم حق الزكاة، وتعم حق الصلة، فإذا تيسر أنه يعطيه حق الصلة، ويغنيه بذلك وهو يقدر؛ كفاه عن الزكاة، وإذا كان لا يستطيع أن يكفيه؛ أعطاه من الزكاة، أو كمل له من الزكاة.","link":"https://binbaz.org.sa/fatwas/1781/عموم-قوله-وات-ذا-القربى-حقه-في-الزكاة-والصلة-وغيرهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_620.mp3","categories":["صدقة التطوع","الآداب والأخلاق المحمودة"]},{"id":6261,"question":"وآت ذا القربى حقه أليس ذلك الزكاة، أو هي نفقة خاصة دون الزكاة؟","title":"عموم قوله: (وَآتِ ذَا الْقُرْبَى حَقَّهُ) في الزكاة والصلة وغيرهما","answer":"الجواب: \nهذا عام، إيتاء ذي القربى حقه، صلة الرحم حق، إذا كان فقيرًا؛ يعطى حقه صلة الرحم، وإذا كان عاجزًا؛ أعطاه من الزكاة، فكل هذا له حق في الزكاة، وله حق في مال قريبه إذا كان فقيرًا، فالآية تعم هذا، وهذا، تعم حق الزكاة، وتعم حق الصلة، فإذا تيسر أنه يعطيه حق الصلة، ويغنيه بذلك وهو يقدر؛ كفاه عن الزكاة، وإذا كان لا يستطيع أن يكفيه؛ أعطاه من الزكاة، أو كمل له من الزكاة.","link":"https://binbaz.org.sa/fatwas/1781/عموم-قوله-وات-ذا-القربى-حقه-في-الزكاة-والصلة-وغيرهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_620.mp3","categories":["صدقة التطوع","الآداب والأخلاق المحمودة"]},{"id":6774,"question":"عمي أوصى بثلث ماله وقفًا لله تعالى، ولم يحدد هذا الوقف، فهل يجوز إرسال بعض هذا المال إلى المتضررين بالمجاعة في السودان، وغيره، مع عدم معرفة هل تصل إلى المسلمين، أو غير المسلمين؟","title":"حكم صرف الوقف لمتضرري المجاعة والتصدق على الكفار","answer":"الجواب: نعم، نعم، إذا كان الوقف في وجوه البر، وأعمال الخير، أو قال وقفًا لله، أو في طُعِمْ كما يقول بعض البادية، أو في وجوه البر، أو في وجوه الخير، أو قال وقفًا لله، وسكت؛ يصرف في وجوه الخير، ولا مانع أن يعطى منه المتضررون من السودان، وغير السودان، حتى ولو كان فيهم غير المسلمين ممن لهم أمان لغير المسلمين؛ لأنهم تجوز فيهم صدقة التطوع، الكفار يعطون من صدقة التطوع، كما قال الله -جل وعلا-: لَا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ [الممتحنة:8] فأخبر سبحانه أنه لا ينهانا أن نبرهم ونقسط إليهم إذا كانوا ليسوا حربا لنا. وهكذا ثبت في الصحيح عن أسماء بنت أبي بكر -رضي الله تعالى عنهما- أن أمها وهي مشركة جاءت إليها في المدينة -في وقت الهدنة- تطلبها مالًا، فقالت أسماء: يا رسول الله، ماذا ترى في ذلك؟ فقال: صليها فأمرها أن تصل أمها وهي مشركة.  فالمقصود: أن صلة المشرك بالمال المتطوع به إذا كان ليس حربًا لنا -كالمستأمن والمعاهد والذمي ونحو ذلك- لا بأس، إنما الذي ينهى عنه، ولا يجوز وصله إذا كان حربًا لنا، إذا كان بيننا وبينهم الحرب، وعدم الأمان، وعدم العهد؛ فهذا هو الذي لا يعطى شيئًا، لا قليلًا ولا كثيرًا.  فأما الصدقة على الفقراء، والمساكين، والذين لا حرب بيننا وبينهم، فلا حرج في ذلك من غير الزكاة، أما الزكاة فلا تصرف إلا للمسلمين عند جمهور أهل العلم.","link":"https://binbaz.org.sa/fatwas/2653/حكم-صرف-الوقف-لمتضرري-المجاعة-والتصدق-على-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1149.mp3","categories":["الوقف","صدقة التطوع"]},{"id":6885,"question":"ما رأيكم -جزاكم الله- في ثلث مال والدي المتوفي، المسمى بالسبيل، هل يجوز لي آكل منه أنا وعيالي، مع العلم أنه ماشية، وعيالي يربونه، ويتعبون فيه؟","title":"حكم الأكل مما أوقف الوالد السبيل","answer":"الجواب: إذا أوصى والدك بالثلث في أعمال البر .. كما هي عادة البادية، فإنك تأكل منه أنت وأهلك إذا كنت محتاجًا إليه، تأكل منه بالمعروف، في ملبسك، ومأكلك، وضيفك، ونحو ذلك بالمعروف. وكذلك إذا كان أولادك يخدمون هذا الثلث، ويتعبون فيه؛ لك أنت وأولادك الأكل بالمعروف. وإذا أغناك الله عنه، ولم يكن لك فيه حاجة؛ فالأولى أن توفره لأعمال الخير، لمساعدة الفقراء، والمساكين، وللمساعدة في أعمال الخير، كبناء المساجد، وقضاء الدين عن المدينين، ونحو ذلك. وإذا احتجت إلى ذلك؛ فأنت أولى من غيرك في حاجتك خاصة، من غير أن تتخذ منه أموالًا، ومساكن، ونحو ذلك، بل تأخذ حاجتك، تأكل حاجتك فقط، وحاجة أهل بيتك، وإذا جعلت فيه من يقوم عليه بالأجرة المعتادة من أولادك، أو غيرهم، يقوموا عليه إذا كان غنمًا، أو إبلًا؛ فلا بأس أن تعطيه الأجرة المعتادة.","link":"https://binbaz.org.sa/fatwas/2775/حكم-الاكل-مما-اوقف-الوالد-السبيل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1267.mp3","categories":["الوقف","صدقة التطوع"]},{"id":6954,"question":"والدي يكنز أموالاً كثيرة، فضة، وورق، ولا يخرج زكاتها، علمًا بأني أنصحه، وأحذره من عذابها، ولكنه لم يسمع، وهو بخيل فيما أرى -والعلم عند الله- ما هو الذي يجب علي نحو والدي؟ كيف يخرج زكاتها وهي لها مدة ثلاثين سنة؟ كيف أقنعه حتى يزكيها؟ هل إذا أراد مني فلوسًا أعطيه، أم أرفض، علمًا أنه يريد كنزها؟ هل على والدتي ذنب إذا أخذت من ماله وهو لا يعلم، علمًا بأنه لا يرضى لشدة بخله -والعياذ بالله-؟","title":"نصيحة إلى من يكنز المال ولا يزكيه","answer":"الجواب: عليك أن تنصحه دائمًا بالكلام الطيب، والأسلوب الحسن؛ حتى يؤدي الزكاة، وإذا استعنت على هذا بأعمامك، وأخوالك حتى ينصحوه طيب، تقول لأخوالك وأعمامك وجيرانك الطيبين ينصحونه بالكلام الطيب، والأسلوب الحسن؛ لعل الله يهديه حتى يخرج الزكاة. وإذا كنت مليًّا تقول: يا أبي أنا أخرج عنك الزكاة، وإذا سمح لك؛ تؤدي عنه -وليس هذا بكثير في بر والدك- إذا سمح لك، وأنت ذو مال؛ تؤدي عنه، كالوكيل من مالك، ولا بأس، وتكون محسنًا في ذلك، فإن مات، ولم تؤدوا عنه، ولم يؤد؛ تؤدونها بعد الموت، تؤدون زكاتها بعدد السنين التي مضت من هذا المال المكنوز، تؤدونه عنه. وإذا أمكن أن يرفع أمره إلى المحكمة حتى تلزمه بذلك -إذا كان عندكم بينة على هذا- ورفعتم أمره إلى المحكمة حتى تلزمه؛ هذا لا بأس به، بل يجب رفع أمره حتى تلزمه المحكمة بأداء الواجب من زكاة ماله، أو هيئة الأمر بالمعروف. هذا من التعاون على البر والتقوى، لكن دون الشكوى، التعاون مع أخوالك، وأعمامك، وإخوتك الكبار، ومن يعزهم أبوك، تتعاونوا بالكلام الطيب، والأسلوب الحسن؛ حتى يزكي، يكون أولى من شكواه إلى المحكمة، وأحسن، وإذا استطعت أنت أن تزكي عنه من مالك بإذنه؛ فهذا أطيب، وأطيب.","link":"https://binbaz.org.sa/fatwas/2884/نصيحة-الى-من-يكنز-المال-ولا-يزكيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1332.mp3","categories":["التفسير","صدقة التطوع","مسائل متفرقة في الزكاة"]},{"id":7992,"question":"هذه الرسالة وردتنا من نايف غزاي العتيـبي ، يقول في رسالته في الحقيقة أنها في عليها طول قليل لكن الخط غير واضح لكن مفادها يقول: إنني أريد أن أركب ثلاجة أو برادة في الشارع في وقت الصيف، ولأن لي مسكن يقع على شارع عام، وأرغب في الأجر من الله عز وجل لي ولوالدي، وأنا مستعد بشراء الثلاجة وتركيبها وتركيب مصارفها إلا أن الماء الذي يأتي إليها يأتي من مصلحة المياه، فهل في ذلك شيء؟ أم أنه يجب علي أن أوفر الماء من غير هذه المصلحة علماً أنني إذا جاء تسديد الفواتير فسوف أسدده من مالي الخاص، هل لي أجر في ذلك أم لا؟","title":"حكم وضع ثلاجة تبريد ماء في الشارع","answer":"الجواب: لا نعلم في هذا بأساً، بل مأجور ومشكور، هذا عمل صالح طيب له أجر ولوالديه أجر، المقصود: أن هذا عمل صالح لا نعلم فيه شيئاً. نعم. ما دام أنه يسدد، يأخذ بطريقة شرعية من الماء المعروف الذي يسرته الحكومة لا بأس، أقول: لا حرج فيه.\nالمقدم: لا حرج فيه إن شاء الله.\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/5547/حكم-وضع-ثلاجة-تبريد-ماء-في-الشارع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_073/07307.mp3","categories":["صدقة التطوع"]},{"id":8361,"question":"شيخ عبد العزيز أولى رسائل هذه الحلقة، رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، تقول الحائرة: (ن. ن) من جدة، أختنا تقول في أحد أسئلتها في هذه الرسالة: ذات يوم احتجت إلى بعض المال، واضطررت إلى السرقة، فسرقت من إحدى الفتيات وتتابع ذلك معي، والآن قد تبت إلى الله وبكيت كثيراً على ما اقترفت يداي، ولا أدري ماذا أفعل؟ وأنا خائفة من عقاب الله وناره، خصوصاً أنه لا يمكنني رد هذه الأموال؛ لأن أصحابها قد سافروا ولا أعرف أين هم، فهل أتصدق بمبلغ يساوي تلك الأموال، أم ماذا أفعل؟","title":"حكم التصدق بالمال المسروق الذي لا يعلم مكان صاحبه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفهذا المال الذي سرقت من الفتاة، وجهلت محلهم الآن، عليك أن تتصدقي به على الفقراء والمساكين، أو في المشاريع الخيرية، بالنية عن صاحبة المال، وتبرأ الذمة إن شاء الله مع التوبة الصادقة والندم، أما إن قدرت على إيصاله إلى الفتاة فعليك ذلك، لكن ما دمت لا تقدرين ولا تعلمين محلهم فالصدقة تكفي مع التوبة الصادقة. نعم.","link":"https://binbaz.org.sa/fatwas/6210/حكم-التصدق-بالمال-المسروق-الذي-لا-يعلم-مكان-صاحبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_114/11401.mp3","categories":["صدقة التطوع"]},{"id":9285,"question":"الأخت عائشة الحجيلي تسأل وتقول: هل يجوز أن نبعث الصدقة إلى الجمعيات الخيرية وهي تقوم بتوزيعها على الفقراء؟","title":"حكم دفع الصدقة لللجمعيات الخيرية","answer":"الجواب: نعم، إذا كانت الجمعية موثوقة والقائمون عليها ثقات لا بأس ترسل الصدقة إليهم زكاة أو غير زكاة وهم يتولون توزيعها. نعم.","link":"https://binbaz.org.sa/fatwas/7449/حكم-دفع-الصدقة-لللجمعيات-الخيرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_154/15414.mp3","categories":["صدقة التطوع"]},{"id":9311,"question":"هل يجوز للمرأة أن تتصدق على أبويها عند موتهما من مال زوجها؟","title":"حكم تصدق الزوجة عن أبيها من مال زوجها","answer":"الجواب: إذا سمح بذلك، وإلا فليس لها ذلك، لكن تتصدق من مالها، من مالها تتصدق على الفقراء والمساكين في أي وقت، أما من مال الزوج فلابد من إذنه. نعم.","link":"https://binbaz.org.sa/fatwas/7475/حكم-تصدق-الزوجة-عن-ابيها-من-مال-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_184/18410.mp3","categories":["صدقة التطوع"]},{"id":9530,"question":"أولى رسائل هذه الحلقة هي رسالة كمال محمد الحسن أحمد نور الدين من السودان الإقليم الشمالي، كنا عرضنا سؤالاً سابقاً عن الاطلاع على التوراة والإنجيل في حلقة مضت، وها نحن نعرض بقية أسئلة الأخ كمال في هذه الحلقة: يقول الله تعالى: وَالَّذِينَ فِي أَمْوَالِهِمْ حَقٌّ مَعْلُومٌ ۝ لِلسَّائِلِ وَالْمَحْرُومِ [المعارج:24-25] أرجو توضيح معنى الآية؛ لأن الذي دعاني لهذا أنه يقف أمامي شخص تدل ملامحه على أنه قوي يستطيع العمل والكسب من عمل يده، وطلب مني أن أعطيه مالاً صدقة فهل يجوز لي التصدق على أمثال هؤلاء أفيدوني أفادكم الله؟","title":"حكم التصدق على من ظاهره القدرة على الكسب","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فيقول الله سبحانه: إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَعُيُونٍ ۝ آخِذِينَ مَا آتَاهُمْ رَبُّهُمْ إِنَّهُمْ كَانُوا قَبْلَ ذَلِكَ مُحْسِنِينَ ۝ كَانُوا قَلِيلًا مِنَ اللَّيْلِ مَا يَهْجَعُونَ ۝ وَبِالأَسْحَارِ هُمْ يَسْتَغْفِرُونَ ۝ وَفِي أَمْوَالِهِمْ حَقٌّ لِلسَّائِلِ وَالْمَحْرُومِ [الذاريات:15-19].\nالحق اختلف فيه العلماء فقيل: هو الزكاة، وقيل: غير الزكاة، فالكمل من المؤمنين يخرجون حقاً من أموالهم للفقراء والمساكين غير الزكاة، منافسة في الخير ومسارعةً إلى أعمال البر ومواساة للمحاويج والفقراء فالسائل ومن يسأل ويستجدي فله حق إلا إذا علمت أنه غني لا يستحق الزكاة، فإنه لا يعطى ويبين له أنه لا يجوز له أن يسأل، أما إذا كان مجهولاً لا يدرى عن حاله أو كان معروف الفقر والحاجة فإنه يعطى من الزكاة ويعطى من غيرها من الصدقات، أما المحروم فهو الفقير الذي حرم المال، أو كان ذا مال ثم أصيب بجائحة اجتاحت ماله فصار فقيراً، فإنه يعطى من الزكاة ويعطى من غيرها من الصدقات، وإذا كان المتقدم السائل قوياً فإنه ينصح ويقال له: إنها لا تحل لغني ولا لقوي مكتسب، فإن اعتذر وذكر أنه ما عنده عمل ولا عنده شيء يقوم بحاله يعطى، فقد ثبت عنه ﷺ: أنه سأله رجلان فنظر فيهما فإذا هما جلدان فقال: إن شئتما أعطيتكما ولا حظ فيها لغني ولا لقوي مكتسب فالإنسان قد يكون قوي البدن ولكن لا يجد عملاً فيبقى في حاجة شديدة، وقد تكون له علة داخلية تمنعه من العمل ولكن ظاهر جسمه يقتضي أنه قوي، فإذا أبدى ما يدل على استحقاقه فإنه يعطى ويصدق في ذلك حرصاً على مواساة المحاويج ولأن هذا قد يقع، قد يتيسر المال للقوي وقد لا يتيسر المال، إما لقلة الأعمال في البلد وإما لأسباب أخرى. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7689/حكم-التصدق-على-من-ظاهره-القدرة-على-الكسب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_245/24501.mp3","categories":["صدقة التطوع"]},{"id":10357,"question":"تقول: عندما يأتي المرأة أهلها زائرين ويحضرون لها معهم شيء من طعام وأحبت أن تتصدق منه، فهل هي آثمة إن تصدقت منه بغير إذن زوجها ورضاه؟","title":"حكم صدقة الزوجة مما أهداها أهلها لها ولزوجها","answer":"الجواب: هذا الطعام هدية من أهلها لها ولزوجها، فإذا تصدقت منه لكونه كثيرًأ يفضل عن حاجتها وحاجة زوجها فلا بأس، أما إذا كان بقدر الحاجة فلا إلا بإذنه، لأن الهدية مطلوب أكلها وأكل زوجها من هذه الهدية من هذا الطعام، والمقصود منه أيضًأ مراعاة خاطر الزوج وخاطر الزوجة، والتقرب إليهما بما يسرهما من هذه الهدية، فإذا كانت الهدية بقدر الحاجة فلا، أما إذا كانت الهدية واسعة كثيرة كالطعام الذي يفضل فالصدقة منه خير من أن يفسد ويضيع. نعم.\nالمقدم: جزاكم الله خيرًأ.","link":"https://binbaz.org.sa/fatwas/8521/حكم-صدقة-الزوجة-مما-اهداها-اهلها-لها-ولزوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_338/33808.mp3","categories":["صدقة التطوع"]},{"id":11041,"question":"هل غرس أشجار الفواكه من الصدقة الجارية، وهل تنتهي هذه الصدقة بعد موت هذه الأشجار؟ كما أرجو من سماحة الشيخ أن يدلنا على الأمثلة على الصدقات الجارية جزاه الله خيرًا.","title":"أنواع من الصدقة الجارية","answer":"الجواب:  الشجر النافع إذا غرسه وقفًا لوجوه الخير، غرس رمانًا، غرس عنبًا ليتصدق بذلك، يكون تبع الوقف، يكون أوقافًا، غرس نخلًا يريده وقفًا في وجوه الخير، وأعمال الخير، لا بأس بذلك، يكون صدقة، يتصدق بثمرته، في وجوه الخير، إذا أراد به الخير وأعمال الخير وقفًا لله  أو بنى بيتًا، أو شرى بيتًا لإسباله، جعله وقفًا لله، أو مزرعة، أرضًا تزرع ويتصدق بغلتها لوجوه البر، وأعمال الخير كل هذا من باب الوقف الشرعي، من باب الصدقة. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9219/انواع-من-الصدقة-الجارية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_287/28723.mp3","categories":["صدقة التطوع"]},{"id":11049,"question":"السائل فراج عبدالسلام مصر المنيا يقول: نريد البيان في هذا السؤال -جزاكم الله خيرًا يا سماحة الشيخ- ما حكم ومصير الأموال التي يكتسبها العبد من الحرام؟ فقد تاب إلى الله، ثم تصدق بهذه الأموال، فهل يؤجر عليها؟ أفتونا مأجورين.","title":"بيان القول في أجر من تصدق بمال حرام","answer":"الجواب:  يؤجر على التوبة، توبته من الحرام، وعليه أن يؤدي الأموال إلى أهلها إن كان أخذها نهبة، أو سرقة يردها إلى أهلها، والتوبة يأجره الله عليها، ويمحو عنه ما سلف، لكن عليه أن يرد المال والدراهم إلى أهلها، فإن كان ما يعرفهم يتصدق بها عنهم بالنية عنهم، مع التوبة إلى الله، والله يأجره على توبته سبحانه، وعلى تخليص ذمته من هذه الأموال التي أخذها بغير حق.","link":"https://binbaz.org.sa/fatwas/9227/بيان-القول-في-اجر-من-تصدق-بمال-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_288/28805.mp3","categories":["صدقة التطوع"]},{"id":11071,"question":"هذه السائلة من جدة -أم عبدالرحمن- تقول: أريد أن أتصدق على روح والدتي بمبلغٍ من المال، فهل يجوز أن أُعطي لأخي هذا المبلغ؛ حيث أنه ذو عيالٍ، وعليه ديونٌ كثيرةٌ؟","title":"حكم الصدقة على ذي الرحم","answer":"الجواب: نعم، نعم، فهي أفضل؛ صدقةٌ وصِلةٌ، صرف المال في أخيك، أو في عمك، أو نحوه من المحتاجين يكون فيه أجران: أجر الصدقة، وأجر صِلة الرحم، فهذا أفضل من الصدقة على البعيد، يقول ﷺ: الصدقة على الفقير صدقةٌ، وعلى ذي الرحم اثنتان: صدقةٌ وصِلةٌ. نعم.","link":"https://binbaz.org.sa/fatwas/9249/حكم-الصدقة-على-ذي-الرحم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_288/28819.mp3","categories":["صدقة التطوع"]},{"id":11186,"question":"من المملكة الأردنية الهاشمية رسالة بعثها مستمع يقول: المرسل علي من الأردن، يسأل عن السبع التي تجري أو يجري على الميت أجرهن في قبره؟","title":"الأعمال التي يلحق الميت أجرها في قبره","answer":"الجواب:  هذا يحتاج إلى تأمل، الصدقة الجارية هذه تتبعه في قبره مثل وقف لله وقفه، فإن أجره يجري له، مثل: صدقة أجراها له بعض أقاربه أو غيرهم، مثل: علم علمه الناس، فيبقى له أجره فيما علم الناس: قرآن أو علم نافع، مثل أشياء وقفها مثل: مصاحف، أو كتب اشتراها وقفها ووزعها للناس يجري عليه أجرها، وهكذا.. كل شيء له فيه أسباب فعله لله وبقي يكون له أجره. نعم. المقدم: إذًا ليست منحصرة في سبع؟ الشيخ: ما أذكر انحصارها في سبع، أقول: ما أذكر أن هناك انحصارًا في سبع. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9371/الاعمال-التي-يلحق-الميت-اجرها-في-قبره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37216.mp3","categories":["صدقة التطوع"]},{"id":11213,"question":"بعد هذا رسالة وصلت إلى البرنامج من مستمع رمز إلى اسمه بالحروف (ح. ب. أ) يسأل جمعًا من الأسئلة من بينها سؤال يقول: هل تصح الصدقة إلى الأقارب أم لا؟ وهل نرد صدقاتنا ونتصدق بطعام أو مال، جزاكم الله خيرًا.","title":"فضل الصدقة على الأقارب الفقراء","answer":"الجواب:  نعم الصدقة في الأقارب صلة وصدقة، فيها أجران: أجر الصلة، وأجر الصدقة، إذا كانوا فقراء، فهم أولى من غيرهم، والصدقة فيهم مضاعفة، وهي صلة رحم وصدقة، وأما الأغنياء تكون هدية، إذا أهديت إليهم فهذا من صلة الرحم، ..... هذه من صلة الرحم ومن أسباب المحبة والمودة والتقارب وصفاء القلوب. فعليكم بالصدقة، أوصيك أيها السائل! وغيرك ممن يسمع هذه الكلمة أوصي الجميع بالصدقة، والكلام الطيب، والدعاء للمسلمين، والدعاء لأقاربك وإخوانك بالتوفيق والهداية، وصلاح النية والقول والعمل، كل هذا مطلوب. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9401/فضل-الصدقة-على-الاقارب-الفقراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_373/37308.mp3","categories":["صدقة التطوع"]},{"id":11355,"question":"بعد هذا رسالة من مستمع أو مستمعة آثروا فيها عدم ذكر الاسم، المهم أن الرسالة تضمنت خمسة أسئلة:في أحدها يقول: ظاهرة التسول منتشرة في كثير من البلاد، ما حكم الامتناع عن التصدق على أولئك المتسولين؛ لأننا لا نعلم هل هم محتاجون حقًا أم أنهم محتالون، وحيث ثبت أن كثيرًا منهم ليسوا في حاجة، ولكن اتخذوا من التسول عملًا، فما الواجب تجاههم؟ جزاكم الله خيرًا.","title":"حكم الامتناع عن الصدقة على المتسولين لعدم معرفة حالهم","answer":"الجواب:  السنة الصدقة عليهم، إذا كنت لا تعرف أحوالهم السنة الصدقة عليهم، أو تعرف أنهم فقراء؛ لقول الله سبحانه في مدح المؤمنين المتقين: وَفِي أَمْوَالِهِمْ حَقٌّ لِلسَّائِلِ وَالْمَحْرُومِ [الذاريات:19] وفي الآية الأخرى: حَقٌّ مَعْلُومٌ ۝ لِلسَّائِلِ وَالْمَحْرُومِ [المعارج:24-25]، فأثنى عليهم لإعطاء السائل، فالمحروم: هو الفقير هذا هو السنة، إذا كنت تعرف أنه فقير تعطيه أو لا تعلم حاله.  أما إذا كنت تعلم أنه غني فإنك تنصحه وتزجره وتبين له أن هذا لا يجوز، فالسائل أقسام ثلاثة: سائل تعرف أنه غني لا يعطى يزجر ويعلم، وسائل تجهل حاله يعطى، وسائل معروف أنه فقير يعطى، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9534/حكم-الامتناع-عن-الصدقة-على-المتسولين-لعدم-معرفة-حالهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_378/37811.mp3","categories":["صدقة التطوع"]},{"id":11974,"question":"من مكة المكرمة رسالة بعثت بها إحدى الأخوات، تقول: المرسلة (م) هل يجوز للمرأة إذا أعطاها زوجها مصروف البيت، وبقي من المصروف شيء، هل يجوز لها أن تتصدق بالباقي بدون إذن زوجها؟ جزاكم الله خيرًا.","title":"حكم تصدق المرأة بما زاد عن مصروفها دون إذن زوجها","answer":"الجواب:  الأقرب -والله أعلم- أنه لابد من إذن، إذا بقي شيء؛ تستأذنه، نعم.","link":"https://binbaz.org.sa/fatwas/10159/حكم-تصدق-المراة-بما-زاد-عن-مصروفها-دون-اذن-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_429/42915.mp3","categories":["صدقة التطوع"]},{"id":12686,"question":"يقول: عندما أذهب إلى بلدي في الإجازة آخذ معي بعض المصاحف، وآخذ فرشًا للمسجد، هل هذا يعتبر صدقة جارية، وأيضًا أرجو أن تحدثوني كثيرًا عن الصدقة الجارية؛ ابتغاء مرضاة الله  جزاكم الله خيرًا.","title":"حكم الصدقة على المسجد بالمصاحف والفرش","answer":"الجواب: نعم، المصاحف والكتب العينية، وفرش المسجد من الصدقة الجارية ما دامت ينتفع بها، وهكذا بناء المساجد من الصدقة الجارية، وبناء المدارس لتدريس العلم الشرعي من الصدقة الجارية، وإصلاح الطرق للمسلمين من الصدقة الجارية، وهكذا توزيع الكتب بين الناس الكتب النافعة المفيدة، من الصدقة الجارية، وهكذا إيقاف الأوقاف الشرعية في وجوه الخير، كأن يوقف بيتًا تصرف غلته في فقراء المسلمين، أو في عمارة المساجد، أو في توزيع الكتب المفيدة والمصاحف، كله من الصدقة الجارية. فالصدقة لله تشمل صدقة بالمال، وإيجاد الأوقاف الشرعية النافعة، وبناء المساجد، وجميع ما يبقى نفعه للمسلم، كله يسمى صدقة جارية، تكون هذه صدقة باقية ما دام النفع، ما دام الانتفاع حاصلًا، ما دام الفراش ينتفع به، ما دام الكتاب ينتفع به، ما دام المصحف ينتفع به، ما دام المسجد ينتفع به، وهكذا.. كله صدقة جارية، والمال الذي يبذل في سبيل الله من غلة الوقف من الصدقة الجارية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10896/حكم-الصدقة-على-المسجد-بالمصاحف-والفرش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_417/41714.mp3","categories":["صدقة التطوع"]},{"id":12764,"question":"أختنا (م. ص. ع) من المملكة الأردنية الهاشمية تسأل سؤالها الأخير، فتقول: هل يجوز أن أقطع عن أخي المصروف اليومي لأنه لا يصلي؟","title":"حكم حرمان القريب الصدقة لتركه الصلاة","answer":"الجواب:  إذا رأيت المصلحة في ذلك؛ لعله يتوب، لعله يستقيم بهذا القطع؛ فهذا طيب، أما إذا كان فقيرًا، ولا يبالي بهذا القطع، فإذا أحسنت إليه فلعل هذا أقرب إلى النجاة، لعل الله يهديه بأسباب ذلك. المقصود أن تفعلي ما هو الأصلح، إن رأيت أن القطع أصلح؛ فاقطعي، وإن رأيت أن الاستمرار في الهدية والإحسان إليه أصلح؛ لعله يتوب، لعله يهتدي؛ فافعلي، افعلي ما هو الأصلح في اجتهادك واعتقادك. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10978/حكم-حرمان-القريب-الصدقة-لتركه-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41913.mp3","categories":["صدقة التطوع"]},{"id":13025,"question":"أحد الإخوة المستمعين سوداني هو: أحمد عبدالله أحمد مقيم في المملكة في شقرا، بعث بأسئلة ملخصها كالتالي، يقول في أحدها: بجواري جار مسلم، لكنه لا يصلي، هل لو أعطيته صدقة، أو نحوها أكون مأجورًا؟","title":"حكم إعطاء الصدقة للجار الذي لا يصلي","answer":"الجواب:  الواجب نصيحته، وإنكار عمله السيئ، وهو ترك الصلاة، فإذا استجاب؛ فالحمد لله، وإلا فالواجب هجره، ومقاطعته حتى يصلي؛ لأن ترك الصلاة منكر عظيم، بل كفر أكبر على أصح قولي العلماء، فلا يجوز التساهل معه، بل يجب أن ينصح ويوجه، ويبين له عظم الخطأ في عمله السيئ، ولا يعطى من الزكاة شيئًا حتى يسلم، حتى يصلي. أما صدقة التطوع إذا أعطاه من باب الترغيب، ومن باب الدعوة إلى الله، كما يعطى الكافر المعاهد، والذمي من صدقة التطوع؛ فلا بأس من هذه الحيثية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11242/حكم-اعطاء-الصدقة-للجار-الذي-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_472/47205.mp3","categories":["صدقة التطوع"]},{"id":13036,"question":"مستمع سمى نفسه صالح المبروك بعث برسالة وضمنها جمعًا من الأسئلة:من بينها سؤال يقول: هل تجوز الصدقة على المساجد؟","title":"حكم الصدقة على المساجد","answer":"الجواب:  نعم، الصدقة على المساجد طيب، عمارة المساجد من أفضل القربات، إذا كانت الصدقة تطوع ما هي بزكاة، فإذا بنى مساجد، أو رممها، أو كمل نقصها، أو فرشها؛ فهذا عمل صالح، وقربة إلى الله  لكن من غير الزكاة، أما الزكاة فتكون في الأصناف الثمانية المذكورة في قوله سبحانه: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَاِبْنِ السَّبِيلِ [التوبة:60]  (في سبيل الله) هم المجاهدون، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11253/حكم-الصدقة-على-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_472/47216.mp3","categories":["صدقة التطوع"]},{"id":13451,"question":"السائل يقول في هذا السؤال أيضًا: بعض الناس يذبح شاة ويقول: هي صدقة، لكن لا يعطيها للفقراء والمساكين، بل يأكلها هو وأهل بيته، وجيرانه، وأصحابه، فهل تعتبر هذه صدقة؟","title":"حكم من يتصدق ويأكل صدقته مع جيرانه وأصحابه","answer":"الجواب: إذا كان في جيرانه فقراء كانت صدقتة عليهم، وهذا من باب الإكرام لأهله وجيرانه، ولو كانوا أغنياء لا بأس يؤجر على ذلك؛ لأن إكرام الجار والإحسان إلى الجار فيه خير عظيم، فإذا أحسن إليهم ودعاهم، وأكرمهم؛ فهذا فيه خير عظيم، ولو كانوا أغنياء، وإن كان فيهم فقراء؛ فقد أحسن إليهم أيضًا لفقرهم، ولكونهم جيرانه، كل هذا طيب، والحمد لله، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11750/حكم-من-يتصدق-وياكل-صدقته-مع-جيرانه-واصحابه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_516/51616.mp3","categories":["صدقة التطوع"]},{"id":13636,"question":"السائل يقول: امرأة تتصدق من مال زوجها، فلما علم قال: لا أسمح لك، وكلمته عن زكاة ماله بأن ذلك من زكاة ماله، ولكنه رفض بشدة، فما الحكم في ذلك؟","title":"حكم تصدق المرأة من مال زوجها دون إذنه","answer":"الجواب: لا تتصدق بماله، إذا رفض لا تتصدق إلا بالشيء الذي يسمح به، والذي لا يسمح به لا تتصدق به، أما إذا اتفقوا فهم شركاء في الأجر، إذا سمح فهي شريكة؛ له أجره بما اكتسب، ولها أجرها بالمساعدة في النفقة، والخازن الخادم معهم شريك أيضًا إذا توافقوا على هذا الشيء، أما إذا منعها فإنها لا تتصدق بمال من ماله إلا بالشيء الذي جرت العادة بالصدقة به بسماحة، فضل الطعام، فضل الغداء، فضل العشاء، الذي جرت العادة بأنه يسمح به. أما شيء لا يسمح به؛ فلا تتصدق به، عليها السمع والطاعة؛ لقول النبي ﷺ: ليس للمرأة عطية إلا بإذن زوجها يعني من ماله، ولكن لا مانع أن تنصحه تقول: يا فلان! هذا خير، وهذا تعاون على البر والتقوى، لعلك تسمح لي، أو تحدد محد تقول له: اسمح لي أتصدق كل يوم بعشرة.. بعشرين، أتصدق بشيء من الطعام، تتفق معه على شيء بالأسلوب الحسن، بالكلام الطيب؛ لعل الله يهديه حتى يسمح لها، فإن أصر، ولم يسمح؛ فليس لها أن تتصدق من ماله بشيء، ولكن تتصدق من مالها هي. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11967/حكم-تصدق-المراة-من-مال-زوجها-دون-اذنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52811.mp3","categories":["صدقة التطوع"]},{"id":13957,"question":"السؤال الأخير لأختنا تقول فيه: ما حكم الشرع فيمن يعطي للفقراء أو يتبرع من مال أبيه أو يعطي من يطلب حاجة من البيت دون أن يخبر أباه أو أمه وهو لا يعلم أنهم هل سيوافقون أو لا؟","title":"حكم التصدق من مال الوالدين دون علمهم","answer":"الجواب: ليس له أن يتصرف إلا بإذن صاحب المال، إن كان المال مال أمه يستأذنها، وإن كان المال من مال أبيه يستأذن أباه، إلا ما كان معروفًا بينهم أنه لا بأس به كفضل الطعام وأشباه ذلك مما جرت العادة بأنه يصرف في الفقراء فلا بأس، أما الشيء الذي لم تجر العادة بينهم أنه يخرج إلا بإذن فإنه يستأذن، والشيء الذي جرت العادة بأنه لا يحتاج إلى إذن لا يحتاج إلى إذن، والناس يختلفون في العرف البلاد والقرى والبوادي يختلفون في هذا، فإذا كان يعرف الولد أن من عرف أبيه وأمه أنهما لا يمانعان في الصدقة بهذا الشيء الذي فعله فلا بأس، وإذا كان يشك في ذلك فليستأذن، إن كان من مال أمه يستأذنها، وإن كان من مال أبيه يستأذنه، وليس له أن يتصرف إلا بإذنهما فيما لا يعلم أنهما يسمحان به، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/12373/حكم-التصدق-من-مال-الوالدين-دون-علمهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_604/60417.mp3","categories":["صدقة التطوع"]},{"id":14323,"question":"السائل أبو أحمد يقول: أسأل عن الوقف وما هو الأفضل فيه الصدقة أم الوقف؟","title":"ما الأفضل للمسلم الوقف أم الصدقة؟","answer":"الجواب: هذا فيه تفصيل: قد تكون الصدقة أفضل في حياة الإنسان يقدم الخير لنفسه قبل وفاته، وقد يكون الوقف أفضل إذا كان خلفه من يحسن القيام على الوقف، ويحسن التصرف حتى تكون صدقة جارية له تنفعه.\nوالأحسن أن يجمع بين الأمرين، يتصدق في حياته وينفق ويوقف ما ينفعه بعد وفاته ويجعلها على يد الثقة الذي يظن فيه الخير وأنه ينفذ ما يقول له؛ لأن الرسول ﷺ: أمر عمر أن يوقف، قال -في أرض له في خيبر- تصدق بأصلها لا يباع ولا يوهب ولكن ينفق ثمره وقال: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية أو علم ينتفع به أو ولد صالح يدعو له. فالوقف في وجوه البر وأعمال الخير مطلوب وجيد ونافع، والصدقة في الحياة وتنجيزها نافع أيضًا.\nفالمسلم يجمع هذا وهذا، يتصدق ويحسن في حياته ويبادر بالخير، وإذا وقف وقفًا بعد وفاته يجمع بين الحسنيين، يكون الوقف في وجوه الخير وأعمال البر كعمارة المساجد والصدقة على الفقراء من أقاربه وغيرهم، والمحتاجين من أقاربه وغيرهم والإنفاق في سبيل الله في تعليم العلم.. في توزيع الكتب.. شراء المصاحف وتوزيعها.. إلى غير هذا من وجوه البر، ويكون على يد الثقة من أقاربه أو غيرهم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12790/ما-الافضل-للمسلم-الوقف-ام-الصدقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_550/55008.mp3","categories":["الوقف","صدقة التطوع"]},{"id":16049,"question":"سماحة الشيخ في حلقة مضت عرضنا على سماحتكم سؤالًا من الأخت المستمعة فريحة حامد الشريف من ليبيا، وكان ذلكم السؤال عن صدقة الفطر، هل يجوز إعطاؤها لغير المسلمين، ضاق وقت الحلقة دون أن تتفضلوا ببيان هذا الوجه الشرعي، وهذه السياسة الشرعية لإعطاء غير المسلمين من الزكاة، بودنا أن تستهلوا هذه الحلقة بالحديث عن هذا الموضوع، وعن تلكم السياسة الشرعية؟ جزاكم الله خيرًا.","title":"حكم دفع الصدقة لغير المسلمين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فقد شرع الله  للمسلمين أن يحسنوا إلى غيرهم من الكفار، وغير الكفار، وأن يعطوا المؤلفة قلوبهم من الزكاة وغيرها؛ تأليفًا لقلوبهم على الإسلام، وتقويةً لإيمانهم، ودعوةً لغيرهم إلى الدخول في الإسلام، ودفعًا لشر من يخشى شره، ولهذا قال -جل وعلا-: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ [التوبة:60] الآية، فجعل لهم نصيبًا من الزكاة، قال جماعة من العلماء: هم السادة المطاعون في عشائرهم، يعني هم الكبراء، والأعيان الذين إذا أعطوا؛ نفع العطاء فيهم بقوة إيمانهم، أو بإسلامهم إن كانوا كفارًا، أو بإسلام نظرائهم، أو بدفع شرهم إذا كان يخشى شرهم، كل هذا من السياسة الشرعية. ويجوز أن يعطوا من غير الزكاة من بيت المال من صدقات المسلمين؛ تأليفًا لقلوبهم، ودفعًا لشرهم إذا خشي شرهم، ودعوة لغيرهم إلى الإسلام، قال الله  في كتابه العظيم في سورة الممتحنة: لا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ [الممتحنة:8]. فأخبر سبحانه أنه لا ينهانا عن هؤلاء الذين لم يقاتلونا في الدين، ولم يخرجونا من ديارنا أن نحسن إليهم، ونبرهم، ونقسط إليهم؛ لما في ذلك من تأليف قلوبهم، وترغيبهم في الإسلام، ودفع شرهم إذا خشي شرهم، فيعطوا من بيت المال، ويعطيهم المسلمون من أموالهم، وصدقاتهم؛ جبرًا لحاجتهم، وسدًا لها، وتأليفًا لقلوبهم، ودعوةً لهم إلى الإسلام، أو حرصًا على قوة إيمانهم إن كانوا مسلمين. وقد ثبت عن النبي ﷺ أنه قال لأسماء بنت أبي بكر -رضي الله عنهما- لما قدمت عليها أمها وقت الهدنة وهي كافرة تريد الصلة والإحسان، قال لها ﷺ: صلي أمك من باب التأليف والإحسان لأمها، وهي على دين قومها في حال الهدنة بين النبي ﷺ وبين أهل مكة، وكان عمر يصل بعض أقاربه في مكة وقت الهدنة . والمقصود: أن الصلة والإحسان للكفار الذين ليس بيننا وبينهم حرب في حال الهدنة، أو في حال العهد، والذمة، أو في حال الأمان إذا رآها ولي الأمر، أو رآها الإنسان مع أقاربه، أو مع غيرهم؛ لا بأس بها، بل فيها تأليف للقلوب، ودعوة إلى الإسلام وترغيب فيه ليعلموا أن الإسلام يرغب في الإحسان، ويدعو إلى الإحسان مع أهله، ومع غير أهله ممن ليس حربًا لنا. وكم حصل بالإحسان من خير عظيم، جماعة كثيرون كانوا يبغضون النبي ﷺ ويعادونه، ولما أحسن إليهم، وواساهم؛ أحبوه، ودخلوا في الإسلام. ومن ذلك صفوان بن أمية  قال : ما هناك أحد أبغض إلي من محمد -عليه الصلاة والسلام- فلم يزل يعطيني، ويعطيني؛ حتى صار أحب الناس إلي، وحتى أدخل الله علي الإسلام. هذا كلامه، أو معناه. وهكذا قال غيره ممن أحسن إليهم النبي ﷺ وقد جاءه أعرابي يسأله، فأعطاه غنمًا، فذهب إلى قومه، وقال: يا قوم! أسلموا فإن محمدًا يعطي عطاء من لا يخشى الفقر. فالمقصود: أن الإحسان في المسلم وغيره ينفع كثيرًا، يقوي إيمان المسلم إذا أعطاه ولي الأمر، أو أعطاه المسلمون، أعطاه إخوانه من زكاتهم، وصدقاتهم، وهو محتاج يقوى إيمانه، ويقوى حبه لإخوانه المسلمين، ويقوى عمله في الإسلام، وإذا أحسن المسلمون إلى غيرهم من الكفار، ولاسيما الرؤساء والكبار، كان ذلك فيه خير عظيم، فيه دعوة لهم إلى الإسلام، وإخبار لهم بما في الإسلام من الخير والإحسان والجود على خصومه إذا لم يكونوا حربيين. فالإسلام يأمر بالإحسان والجود والكرم في فقراء المسلمين، وفي فقراء غيرهم ممن لهم ذمة، أو أمان، أو عهد، يتألفهم بذلك المؤمن، ويدعوهم إلى أن يدخلوا في الإسلام، ويحبب الإسلام إليهم. فينبغي للمؤمن أن يلاحظ ذلك مع أقاربه، ومع جيرانه إذا كان في بلد فيها كفار، وهناك أمن بينهم لا حرب أن يحسن إليهم حتى يرغبهم في الإسلام، وحتى يقوي إيمانهم إن كانوا مسلمين. أما الزكاة فتدفع إلى الرؤساء والكبار عند الجمهور، إنما تدفع للرؤساء، والأعيان، والسادة؛ تأليفًا لهم إن كانوا مسلمين، وتقوية لإيمانهم، ودعوة لهم إلى الإسلام إن كانوا غير مسلمين، ودعوة لغيرهم من نظرائهم، ودفعًا لشرهم إن كان فيهم شر. أما صدقة التطوع فهي عامة للرؤساء، وغير الرؤساء من الكفار الذين ليس بيننا وبينهم حرب يعطون من المال، ويحسن إليهم بغير المال من شفاعة تنفعهم، أو تفريج كربة، أو دفع شر عنهم؛ ليرغبوا في الإسلام، وليتوجهوا إليه بقلوبهم، وليعرفوا فضله وفضل أهله، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا، سماحة الشيخ: الواقع هذا الوجه من السياسة الشرعية يجهله كثير من المسلمين. الشيخ: صحيح. المقدم: تتفضلون بكلمة حول هذا جزاكم الله خيرًا. الشيخ: لاشك أن هذا الأمر يجهله الكثير من الناس، فينبغي أن يعلم، ولهذا جعل الله للمؤلفة قلوبهم حقًا في الزكاة، وحقًا في بيت المال، فعلى ولي الأمر أن يلاحظ ذلك، وأن يعتني بالمؤلفة قلوبهم؛ حتى يكونوا عونًا للمسلمين، وحتى يرغبوا في الإسلام، أو يكفوا شرهم عن المسلمين. وهكذا أفراد المسلمين يحسنون في جيرانهم إذا كانوا في بلاد فيها كفار، يحسنون إليهم، ويرغبونهم في الإسلام، ويعطونهم من صدقاتهم ما يرغبهم في الإسلام، وإذا كانوا من السادة والكبراء أعطوهم أيضًا من الزكاة؛ لعلهم يسلمون، أو يسلم نظراؤهم، وأشباههم، نسأل الله أن يفقه المسلمين في دينه، وأن يعينهم على كل خير. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14678/حكم-دفع-الصدقة-لغير-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_802/nour_80201.mp3","categories":["صدقة التطوع"]},{"id":16578,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: أخوكم (هـ. ف. ع) يسأل عددًا من الأسئلة: يقول في أحدها: هل يجوز لي أن أتصدق من مال أبي، وهو لا يعرف، علمًا بأنه مغترب، وإن كان موجودًا هل يجوز ذلك؟ علمًا بأن الصدقة قليلة، ولا تؤثر في المال؟","title":"حكم التصدق من مال الأب دون علمه","answer":"الجواب: إذا كانت الصدقة جرت بها العادة، وأبوك يسمح بها مثل فضول الطعام... ما يفضل من الطعام؛ لا بأس، أو شيئًا قد سمح به أبوك، كانت الصدقة شيئًا سمح به أبوك لك، ولأهل بيتك؛ فلا بأس، وإلا فلابد من إذنه؛ لأن المال ماله، فلابد من إذنه في الصدقة، وإذا أخذتم بالقاعدة، قلتم له: نتصدق بكذا، وسمح لكم فلا بأس، الشيء الذي جرت به العادة أنه يسمح به، فأخرجوه من دون حاجة للإذن، مثل فضول الطعام، مثل سقي الماء، مثل إعارة المتاع الذي يحتاجه الناس، لا بأس إذا كان والدك قد عرفتم منه السماح بهذه الأمور، نعم. المقدم: جزاكم الله خيرًا، إذًا يتصلون بوالدهم عبر الهاتف، أو عبر رسالة بريدية، ويستأذنونه فيما يريدون؟  الشيخ: نعم، نعم.  الشيخ: إلا الشيء يعرفون أنه يسمح به. المقدم: بارك الله فيكم، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15309/حكم-التصدق-من-مال-الاب-دون-علمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75805.mp3","categories":["صدقة التطوع"]},{"id":16628,"question":"تقول: في المنزل الذي أسكن فيه يوجد معنا بعض المساكين يسكنون منزلًا مستقلًا، وأعطيهم شيئًا من الطعام كل يوم، دون علم زوجي بذلك، فهل ارتكبت ذنبًا؟","title":"حكم صدقة المرأة من قوت زوجها دون علمه","answer":"الجواب: لا حرج في ذلك، فضل الطعام يعطاه الفقراء، والمساكين، فضل الطعام، ولا حرج في ذلك، وهذا من باب الإحسان، يقول النبي ﷺ في الحديث الصحيح: إذا أنفقت المرأة من طعام بيتها غير مفسدة؛ كان لها أجرها بما أنفقت، ولزوجها أجره بما اكتسب، وللخادم مثل ذلك، لا ينقص بعضهم من أجر بعض شيئًا فإذا أنفقت غير مفسدة للفقراء، والمساكين من فضل الطعام؛ فلك أجر، ولزوجك أجر، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، سماحة الشيخ: قلتم من فضل الطعام، ماذا عن غير هذا القيد؟ الشيخ: الشيء الذي ليس بفضل يستأذن، تستأذن فيه الزوج، إذا كان يسمح، وتعرفين من عادته، ومن خلقه أنه قد فوضك، وأنه لا حرج عنده من تصرفك؛ فأنفقي، وأبشري بالخير، والأجر مشترك. أما إن كنت تعرفين أنه شحيح، وأنه لا يرضى فاستأذنيه.  أما فضل الطعام، فضل طعام الغداء، فضل طعام العشاء؛ أنفقيه، والحمد لله، لا يفسد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15357/حكم-صدقة-المراة-من-قوت-زوجها-دون-علمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_716/nour_71609.mp3","categories":["صدقة التطوع"]},{"id":16646,"question":"احترت كثيرًا فيمن يتسولون هل أعطيهم، أم أمنعهم؟ أفيدونا جزاكم الله خيرًا.","title":"ما حكم إعطاء المتسولين؟","answer":"الجواب: السنة إعطاء المتسول، السنة أن تعطي المتسول، إلا أن تعلم أنه كذاب، وأنه غني؛ لا تعطه، بل انصحه، وقل له: اتق الله، هذا لا يجوز لك، أما إذا كنت تعرف أنه فقير، أو تجهل حاله، لا تعرف حاله، فالسنة أن تعطيه لقول الله  في وصف المؤمنين: وَفِي أَمْوَالِهِمْ حَقٌّ لِلسَّائِلِِ وَالْمَحْرُومِ [الذاريات:19] وفي الآية الأخرى: وَالَّذِينَ فِي أَمْوَالِهِمْ حَقٌّ مَعْلُومٌ ۝ لِلسَّائِلِ وَالْمَحْرُومِ [المعارج:24-25] فالسنة أن تعطي السائل، وتحسن إليه ما دمت لا تعرف عنه أنه كذاب، وأنه غني، تعطيه سواء كان مجهولًا، أو معروفًا لديك بأنه فقير، السنة أن تعطيه، وتحسن إليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15379/ما-حكم-اعطاء-المتسولين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_717/nour_71709.mp3","categories":["صدقة التطوع"]},{"id":17368,"question":"حفظكم الله هذا السائل يقول: هل المحتاجين الذين يقفون عند المساجد تجوز عليهم الصدقة؛ لأنني أعطيهم عند كل مسجد أصلي فيه ما يتيسر من المال، سواء كان ذلك قليلًا، أم كثيرًا، هل هذه الصدقة جارية لي في حياتي، وبعد مماتي، أو أنها تنقطع بعد الممات فقط؟","title":"هل تجوز الصدقة على السائل الذي لا يعلم حاله؟","answer":"الجواب: هذه صدقة نافعة؛ لأن الله يقول: وَالَّذِينَ فِي أَمْوَالِهِمْ حَقٌّ مَعْلُومٌ ۝ لِلسَّائِلِ وَالْمَحْرُومِ [المعارج:24-25] فالسائل يعطى إلا إذا كنت تعلم أنه غني؛ فتنصحه، ولا تعطيه، تنصحه، تقول له: اتق الله، أما إذا كنت لا تعلم حاله، أو تعرف أنه فقير؛ تعطيه من الزكاة وغيرها، والحمد لله.","link":"https://binbaz.org.sa/fatwas/16206/هل-تجوز-الصدقة-على-الساىل-الذي-لا-يعلم-حاله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59328.mp3","categories":["صدقة التطوع"]},{"id":17663,"question":"تقول: إذا كان زوجي يخرج كل شهرٍ مبلغًا من المال، ومن راتبه لله، وأنا أشجعه على ذلك، وقد كان ذلك اقتراح مني، فهل جزاء هذا العمل يذهب ثوابه له وحده؟ أم لي؛ لأنني اقترحته عليه، وهو قام بالتنفيذ؟ جزاكم الله خيرًا.","title":"أجر الدال على الخير","answer":"الجواب: الأجر مشترك لك وله، له الأجر على إنفاقه، ولك الأجر على الدلالة والإرشاد، يقول النبي ﷺ: من دل على خير؛ فله مثل أجر فاعله فأنت لك ثواب الدلالة، والنصيحة، والتشجيع، وهو له ثواب الإنفاق بماله، فكلاكما شريك في الخير. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16593/اجر-الدال-على-الخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_727/nour_72708.mp3","categories":["صدقة التطوع"]},{"id":17677,"question":"عبد الله الحسن له مجموعة من الأسئلة يقول: سماحة الشيخ حفظكم الله! ما حكم الصدقة على والدي الأحياء الأصحاء وهم أغنياء، وهم لا يعلمون بذلك؟","title":"حكم إعطاء الصدقة للوالدين الصحيحين الغنيين","answer":"الجواب: إذا كانوا أغنياء فلا حاجة للصدقة، فإذا كانوا أغنياء فلا حاجة للصدقة، التمس الفقراء أعطهم الصدقة، إذا كان أجدادك أغنياء فالحمد لله، ليسوا في حاجة إلى صدقتك، لكن إذا كان ذلك قد يسرهم ويحصل به صلة الرحم والبر لا بأس، إذا كان الوالدان يسرهم منك أن تهدي لهما ما يسمى صدقة يسمى هدية من باب التحبب إليهما ومن باب الصلة والبر لا بأس ولا يسمى صدقة، إذا أردت الصدقة أعطها الفقراء، أما إذا أهديت إلى والديك أو إلى أجدادك من باب التحبب إليهم من باب الصلة من باب البر فلا بأس.\nالمقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16610/حكم-اعطاء-الصدقة-للوالدين-الصحيحين-الغنيين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59506.mp3","categories":["صدقة التطوع"]},{"id":17730,"question":"السائلة تقول في سؤالها يا سماحة الشيخ: أقوم بالتوفير من مصروفي علمًا بأنها طالبة جامعية تذكر وفي مرحلة الدراسة تدرس، ووالدها هو الذي ينفق عليها، تقول هذه السائلة: وأجمع هذه الأموال وأتصدق بها على الفقراء، فهل لي الأجر مع أن المال ليس لي؟","title":"حكم صدقة الطالب من مصروفه","answer":"الجواب: نرجو لك الأجر، إذا اقتصدت أعطاك الوالد ما يكفيك واقتصدت وتصدقت من ذلك أرجو أن لا يكون في هذا بأس، وأنك مأجورة؛ لأنك اقتصدت لطلب الأجر من الله والإحسان لعباده، فأرجو أن لا حرج في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/16702/حكم-صدقة-الطالب-من-مصروفه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_777/nour_77704.mp3","categories":["صدقة التطوع"]},{"id":17734,"question":"السائلة تقول في سؤالها يا سماحة الشيخ: أقوم بالتوفير من مصروفي علمًا بأنها طالبة جامعية تذكر وفي مرحلة الدراسة تدرس، ووالدها هو الذي ينفق عليها، تقول هذه السائلة: وأجمع هذه الأموال وأتصدق بها على الفقراء، فهل لي الأجر مع أن المال ليس لي؟","title":"حكم صدقة الطالب من مصروفه","answer":"الجواب: نرجو لك الأجر، إذا اقتصدت أعطاك الوالد ما يكفيك واقتصدت وتصدقت من ذلك أرجو أن لا يكون في هذا بأس، وأنك مأجورة؛ لأنك اقتصدت لطلب الأجر من الله والإحسان لعباده، فأرجو أن لا حرج في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/16702/حكم-صدقة-الطالب-من-مصروفه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_777/nour_77704.mp3","categories":["صدقة التطوع"]},{"id":17914,"question":"تسأل أختنا عن هذه الحادثة، فتقول: إنسانٌ لا يعمل، ويصرف ماله فيما لا يفيد، ثم يحتاج إلى لقمة العيش، ليأكلها من شدة الحاجة، فهل إذا أعطيت مثل هذا الشخص؛ أكون ممن فرج كربة أخيه؟ علمًا بأنه لا يعمل تكاسلًا، وإذا حصل على مبلغٍ بطريقٍ ما؛ فإنه ينفقه بسرعة، وأحيانًا لا يجد ما يأكل، جزاكم الله خيرًا.","title":"حكم الصدقة على السفهاء","answer":"الجواب: نعم؛ إذا كانت في الحالة التي لا يجد شيئًا، وأحسن إليه إنسان، فهو قد أحسن إلى أخيه، وفرج كربته، ولكن هذا الذي ذكر؛ لا يكون إلا من إنسانٍ ناقص العقل، ليس بعاقل، بل سفيه، لا يعمل، ومع هذا ينفق ما في يده، ويتعطل؛ هذا لا يكون من العقلاء، لكن متى وجد منه حاجة؛ ......... بما يقوم بحاجته، يسد حاجته، لأن المال الذي بيده ضاع، ذهب، فصار فقيرًا محتاجًا إلى الدعم والمساعدة، فمن دعا أنه ساعده في أن يزيل كربته، ويسد حاجته، فهو مأجور إن شاء الله، كسائر السفهاء المفرطين. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16924/حكم-الصدقة-على-السفهاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_728/nour_72818.mp3","categories":["صدقة التطوع"]},{"id":18084,"question":"من الإخوة: (ع. ع. خ) و (ف. ع. ص) رسالة، وضمناها بعض الأسئلة، في أحدها: اشتريت ذات يومٍ من صاحب بقالة، أعطيته خمسين ريالًا، وأعطاني أربعمائة وخمسين ريالًا، وكنت عارفًا بالخطأ، وحينئذ ندمت، والآن أريد أن أعيد له ما يستحقه عندي، لكني لا أعرف مكانه، كيف تنصحونني أن أتصرف؟ جزاكم الله خيرًا.","title":"كيفية التصرف مع المال المجهول صاحبه","answer":"الجواب: إذا لم تعرف مكانه، ولا عنوانه، فتصدق به بالنية عنه، تعطيه بعض الفقراء بالنية عنه، والله ينفعه بذلك، فإذا جاء بعد حين وعرفته، تخيره، إن شاء قبل الصدقة، وصارت له، وإن شاء أعطيته ماله، وكانت الصدقة لك، والثواب لك، والحمد لله. نعم. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17119/كيفية-التصرف-مع-المال-المجهول-صاحبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_730/nour_73008.mp3","categories":["صدقة التطوع"]},{"id":18965,"question":"رسالة بعث بها المستمع إدريس إبراهيم عوض من ليبيا، أخونا يسأل عن قضية دارت على ألسنة العامة وهي: أنه يجب أن تغسل ملابس الميت جميعها، والتصدق بها، ما هو توجيه سماحتكم؟جزاكم الله خيرًا.","title":"حكم غسل ملابس الميت قبل التصدق بها","answer":"الجواب: ليس على هذا دليل، يتصدق بها، وإن لم تغسل، إلا إذا كان فيها نجاسة تغسل، أما إذا كان ما فيها نجاسة، إن غسلوها لأجل مصلحة الفقير جزاهم الله خيرًا، وإن تصدقوا بها ولم تغسل فلا بأس، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18094/حكم-غسل-ملابس-الميت-قبل-التصدق-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73625.mp3","categories":["صدقة التطوع"]},{"id":18974,"question":"تسأل عن الصدقة على غير المسلمين؟","title":"حكم الصدقة على غير المسلمين","answer":"الجواب: الصدقة على غير المسلمين جائزة إذا كانوا ليس حربًا لنا، إذا كان الكفار ليسوا حربًا لنا في حال أمان وهدنة ومعاهدة ونحو ذلك فلا بأس؛ لقول الله : لا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ [الممتحنة:8] ولأنه ثبت في الصحيحين عن أسماء بنت أبي بكر -رضي الله تعالى عنهما-: «أن أمها وردت عليها في وقت صلح الحديبية حين صالح النبي ﷺ أهل مكة وفدت عليها في المدينة تطلب الرفد منها، فقالت أسماء: يا رسول الله: هل أصلها؟ قال النبي ﷺ: صليها فأمرها أن تصل أمها وهي كافرة. فالحاصل: أن المسلم له أن يصل أقاربه الكفار وغير أقاربه من الكفار بالمال والإحسان إذا كانوا ليسوا حربًا لنا في حال هدنة، أما إذا كانوا حربًا لنا في حال حرب لا، لا يوصلون بشيء، ولا يعانون بشيء، ولا يجوز أن يعانوا بشيء بالكلية، لا قليل ولا كثير. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18117/حكم-الصدقة-على-غير-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_924/nour_92414.mp3","categories":["صدقة التطوع"]}]
